120	/// Parse the `--use-template` value into `(work, bot)` template paths.
121	///
122	/// Format: `WORK[,BOT]`. If `BOT` is omitted, the default is the sibling
123	/// directory whose name is `<WORK-basename>.claude` (via
124	/// `Path::with_file_name`, so a trailing slash on `CODE` does not produce
125	/// a different result).
126	pub(crate) fn parse_use_template(
127	    s: &str,
128	) -> Result<(PathBuf, PathBuf), Box<dyn std::error::Error>> {
129	    let mut parts = s.splitn(2, ',');
130	    let work_raw = parts.next().unwrap_or(""); // OK: splitn always yields at least one element
131	    let bot_raw = parts.next();
132	    let work_trim = work_raw.trim();
133	    if work_trim.is_empty() {
134	        return Err("--use-template: work template path is empty".into());
135	    }
136	    let work = PathBuf::from(work_trim);
137	    let bot = match bot_raw.map(str::trim) {
138	        Some(b) if !b.is_empty() => PathBuf::from(b),
139	        _ => {
140	            let file_name = work.file_name().ok_or_else(|| {
141	                format!(
142	                    "--use-template: cannot derive default bot path from '{}' (no file name component)",
143	                    work.display()
144	                )
145	            })?;
146	            let new_name = format!("{}.claude", file_name.to_string_lossy());
147	            work.with_file_name(new_name)
148	        }
149	    };
150	    Ok((work, bot))
151	}
