160	/// Top-level non-hidden files init writes. Kept here so that if init is
161	/// ever extended to write non-hidden top-level files, the pre-flight
162	/// conflict scan flags any template that would clash. Currently empty
163	/// because init only writes hidden files (`.vc-config.toml`, `.gitignore`),
164	/// and the template copy skips hidden entries.
165	const RESERVED_TEMPLATE_ENTRIES: &[&str] = &[];
166	
167	/// Validate one template directory: exists, is a directory, and has no
168	/// top-level non-hidden entry that would collide with init's own writes.
169	///
170	/// - `label` prefixes every error message (`work` / `bot`).
171	pub(crate) fn validate_template_one(
172	    label: &str,
173	    p: &Path,
174	) -> Result<(), Box<dyn std::error::Error>> {
175	    if !p.exists() {
176	        return Err(format!(
177	            "--use-template: {label} template '{}' does not exist",
178	            p.display()
179	        )
180	        .into());
181	    }
182	    if !p.is_dir() {
183	        return Err(format!(
184	            "--use-template: {label} template '{}' is not a directory",
185	            p.display()
186	        )
187	        .into());
188	    }
189	    for entry in std::fs::read_dir(p)? {
190	        let entry = entry?;
191	        let name = entry.file_name();
192	        let name_str = name.to_string_lossy();
193	        if name_str.starts_with('.') {
194	            continue;
195	        }
196	        if RESERVED_TEMPLATE_ENTRIES.contains(&name_str.as_ref()) {
197	            return Err(format!(
198	                "--use-template: {label} template '{}' contains reserved entry '{}'",
199	                p.display(),
200	                name_str
201	            )
202	            .into());
203	        }
204	    }
205	    Ok(())
206	}
