208	/// Validate both template paths (dual-repo mode). Thin wrapper over
209	/// `validate_template_one` kept for single-call ergonomics.
210	pub(crate) fn validate_templates(
211	    work: &Path,
212	    bot: &Path,
213	) -> Result<(), Box<dyn std::error::Error>> {
214	    validate_template_one("work", work)?;
215	    validate_template_one("bot", bot)?;
216	    Ok(())
