219	/// Recursively copy non-hidden entries from `src` to `dst`. Any entry whose
220	/// file name starts with `.` is skipped. Symlinks are skipped with a debug
221	/// log — templates don't need them, and following them risks escaping the
222	/// template tree.
223	pub(crate) fn copy_template_recursive(
224	    src: &Path,
225	    dst: &Path,
226	) -> Result<(), Box<dyn std::error::Error>> {
227	    for entry in std::fs::read_dir(src)? {
228	        let entry = entry?;
229	        let name = entry.file_name();
230	        let name_str = name.to_string_lossy();
231	        if name_str.starts_with('.') {
232	            continue;
233	        }
234	        let src_path = entry.path();
235	        let dst_path = dst.join(&name);
236	        let ft = entry.file_type()?;
237	        if ft.is_symlink() {
238	            debug!("skip symlink {}", src_path.display());
239	            continue;
240	        }
241	        if ft.is_dir() {
242	            mkdir_p(&dst_path)?;
243	            copy_template_recursive(&src_path, &dst_path)?;
244	        } else if ft.is_file() {
245	            debug!("copy {} -> {}", src_path.display(), dst_path.display());
246	            std::fs::copy(&src_path, &dst_path)?;
247	        }
248	    }
249	    Ok(())
250	}
