252	/// Replace the first line of `<dir>/README.md` with `# <name>`. If
253	/// `README.md` is absent, this is a no-op. Trailing content after the
254	/// first newline is preserved verbatim; a file with no newline becomes
255	/// just `# <name>`.
256	pub(crate) fn rewrite_readme_first_line(
257	    dir: &Path,
258	    name: &str,
259	) -> Result<(), Box<dyn std::error::Error>> {
260	    let readme = dir.join("README.md");
261	    if !readme.exists() {
262	        return Ok(());
263	    }
264	    let content = std::fs::read_to_string(&readme)?;
265	    let rest = match content.find('\n') {
266	        Some(pos) => &content[pos..],
267	        None => "",
268	    };
269	    let new_content = format!("# {name}{rest}");
270	    std::fs::write(&readme, new_content)?;
271	    debug!("rewrote first line of {}", readme.display());
272	    Ok(())
273	}
