297	/// Renders the header comment + active `[repos]` registry for a
298	/// generated `.vc-config.toml`, role-specific.
299	fn render_workspace_header(role: ConfigRole) -> String {
300	    match role {
301	        ConfigRole::DualWork => r#"# vc-config: Vibe Coding workspace configuration
302	#
303	# [repos] is the workspace's repo registry: work and bot are paths
304	# relative to this file's directory (absolute allowed, discouraged).
305	# The entry that resolves to this config's own directory names the
306	# side — work = "." makes this the work repo.
307	
308	[repos]
309	work = "."
310	bot = ".claude"
311	"#
312	        .to_string(),
313	        ConfigRole::DualBot => r#"# vc-config: Vibe Coding workspace configuration
314	#
315	# [repos] is the workspace's repo registry: work and bot are paths
316	# relative to this file's directory (absolute allowed, discouraged).
317	# The entry that resolves to this config's own directory names the
318	# side — bot = "." makes this the bot repo.
319	
320	[repos]
321	work = ".."
322	bot = "."
323	"#
324	        .to_string(),
325	        ConfigRole::WorkOnly => r#"# vc-config: Vibe Coding workspace configuration
326	#
327	# [repos] is the workspace's repo registry: work is this repo's
328	# path relative to this file's directory. Used to resolve changeID
329	# paths in git trailers (e.g. ochid: /changeID).
330	
331	[repos]
332	work = "."
333	"#
334	        .to_string(),
335	    }
336	}
