338	/// Renders a commented block documenting every settable workspace
339	/// config key not already covered by the active `[repos]`
340	/// block above — currently the `push.*` and `bot-session.*`
341	/// families, sourced from `config_schema::schema()` so this list
342	/// cannot drift from the schema.
343	///
344	/// Grouped by TOML section (schema/first-seen order); each key is
345	/// emitted via `config_schema::render_key_block` — a multi-line
346	/// doc-block whose assignment line is `# <leaf> = <value>` (a
347	/// non-`required` key always renders commented, and every optional
348	/// key here is non-`required` by construction — see the
349	/// `workspace.*` skip below), so the whole block parses as
350	/// comments only.
351	fn render_optional_keys_block() -> String {
352	    use crate::config_schema::{Home, render_key_block, schema, section_and_leaf};
353	
354	    let mut out = String::new();
355	    out.push_str(
356	        "\n# Optional keys — uncomment and edit to override the built-in\n\
357	         # default. `vc-x1 config` prints this list from the binary.\n",
358	    );
359	
360	    let mut current_section: Option<String> = None;
361	    for key in schema() {
362	        if key.path.starts_with("repos.") {
363	            continue;
364	        }
365	        if !key
366	            .homes
367	            .iter()
368	            .any(|h| matches!(h, Home::WorkspaceCode | Home::WorkspaceBot))
369	        {
370	            continue;
371	        }
372	        let (section, _leaf) = section_and_leaf(key.path);
373	        if current_section.as_deref() != Some(section) {
374	            // The first section needs a blank line separating it from
375	            // the intro comment above; later sections already inherit
376	            // one from the previous key block's trailing blank line
377	            // (`render_key_block` always ends with one).
378	            if current_section.is_none() {
379	                out.push('\n');
380	            }
381	            out.push_str(&format!("[{section}]\n"));
382	            current_section = Some(section.to_string());
383	        }
384	        if key.default.is_none() {
385	            continue;
386	        }
387	        out.push_str(&render_key_block(key));
388	    }
389	
390	    out
391	}
