393	/// Renders the complete generated `.vc-config.toml` content for
394	/// `role`: the active header + `[repos]` registry, followed by a
395	/// commented block documenting the rest of the settable-key
396	/// surface (see `render_optional_keys_block`).
397	pub(crate) fn render_vc_config(role: ConfigRole) -> String {
398	    let mut out = render_workspace_header(role);
399	    out.push_str(&render_optional_keys_block());
400	    out
401	}
