476	/// Expand `~` and `$VAR` / `${VAR}` substitutions in a user string.
477	///
478	/// - `~` and `~/...` resolve via `HOME`.
479	/// - Unset env vars are a fatal error (silent empty substitution
480	///   would mask typos).
481	/// - Bare `$` with no identifier after stays literal.
482	pub(crate) fn expand_vars(s: &str) -> Result<String, Box<dyn std::error::Error>> {
483	    let home_expanded = if s == "~" {
484	        std::env::var("HOME").map_err(|_| "HOME is not set; cannot expand '~'")?
485	    } else if let Some(rest) = s.strip_prefix("~/") {
486	        let home = std::env::var("HOME").map_err(|_| "HOME is not set; cannot expand '~/'")?;
487	        format!("{home}/{rest}")
488	    } else {
489	        s.to_string()
490	    };
491	
492	    let mut out = String::with_capacity(home_expanded.len());
493	    let mut chars = home_expanded.chars().peekable();
494	    while let Some(c) = chars.next() {
495	        if c != '$' {
496	            out.push(c);
497	            continue;
498	        }
499	        let (name, braced) = if chars.peek() == Some(&'{') {
500	            chars.next(); // OK: peeked '{' above, next() must yield it
501	            let mut name = String::new();
502	            let mut closed = false;
503	            for c2 in chars.by_ref() {
504	                if c2 == '}' {
505	                    closed = true;
506	                    break;
507	                }
508	                name.push(c2);
509	            }
510	            if !closed {
511	                return Err(format!("unterminated '${{...}}' in '{s}'").into());
512	            }
513	            (name, true)
514	        } else {
515	            let mut name = String::new();
516	            while let Some(&c2) = chars.peek() {
517	                if c2.is_ascii_alphanumeric() || c2 == '_' {
518	                    name.push(c2);
519	                    chars.next();
520	                } else {
521	                    break;
522	                }
523	            }
524	            (name, false)
525	        };
526	        if name.is_empty() {
527	            out.push('$');
528	            if braced {
529	                out.push_str("{}");
530	            }
531	            continue;
532	        }
533	        let val =
534	            std::env::var(&name).map_err(|_| format!("env var '${name}' is not set (in '{s}')"))?;
535	        out.push_str(&val);
536	    }
537	    Ok(out)
538	}
