540	/// True when `s` looks like a git remote URL rather than a path.
541	///
542	/// - Scheme-qualified (`scheme://...`).
543	/// - scp-like SSH form (`user@host:path`).
544	/// - Everything else is treated as a path.
545	pub(crate) fn is_remote_url(s: &str) -> bool {
546	    if s.contains("://") {
547	        return true;
548	    }
549	    if let Some(at) = s.find('@')
550	        && let Some(colon) = s.find(':')
551	        && at < colon
552	        && !s[..at].contains('/')
553	    {
554	        return true;
555	    }
556	    false
557	}
