559	/// True when `s` is a GitHub URL (host-based detection).
560	///
561	/// - SSH scp-like (`git@github.com:...`).
562	/// - `ssh://git@github.com/...`.
563	/// - `https://github.com/...` and `http://github.com/...`.
564	/// - GitHub URLs route to the `gh repo create` provisioner.
565	pub(crate) fn is_github_url(s: &str) -> bool {
566	    s.starts_with("git@github.com:")
567	        || s.starts_with("ssh://git@github.com/")
568	        || s.starts_with("https://github.com/")
569	        || s.starts_with("http://github.com/")
570	}
