572	/// Normalize a `--repo local=<parent>` value: expand variables,
573	/// make absolute. Parent doesn't need to exist yet — init creates
574	/// it.
575	pub(crate) fn normalize_local_parent(s: &str) -> Result<PathBuf, Box<dyn std::error::Error>> {
576	    let s = s.trim();
577	    if s.is_empty() {
578	        return Err("--repo local: parent dir is empty".into());
579	    }
580	    let expanded = expand_vars(s)?;
581	    let p = PathBuf::from(&expanded);
582	    if p.is_absolute() {
583	        Ok(p)
584	    } else {
585	        let cwd = std::env::current_dir()?;
586	        Ok(cwd.join(p))
