651	/// Build an `InitPlan` from CLI args + user config.
652	///
653	/// Dispatches on the parsed `<TARGET>` form:
654	///
655	/// - `Url(u)` / `OwnerName(o, n)` -> URL is explicit; config not
656	///   consulted; `--account` and `--repo` are rejected as
657	///   meaningless.
658	/// - `Path(p)` -> `p` is the destination; basename names the repo;
659	///   remote URL resolved from config via the `--repo` chain.
660	/// - `BareName(n)` -> destination at `cwd/<n>`; remote resolved
661	///   from config.
662	///
663	/// The `cfg` parameter is the loaded user config; `init` loads it
664	/// once at entry and passes it through so tests can supply a
665	/// synthetic config without touching disk.
666	pub(crate) fn plan_init(
667	    params: &InitParams,
668	    cfg: &UserConfig,
669	) -> Result<InitPlan, Box<dyn std::error::Error>> {
670	    debug!(
671	        "init args: target={:?}, name={:?}, account={:?}, repo={:?}, por={}, private={}",
672	        params.target, params.name, params.account, params.repo, params.por, params.private
673	    );
674	
675	    let scope = if params.por {
676	        Scope(vec![Side::Work])
677	    } else {
678	        Scope(vec![Side::Work, Side::Bot])
679	    };
680	
681	    if scope.is_work_only()
682	        && let Some(t) = &params.use_template
683	        && t.contains(',')
684	    {
685	        return Err(format!(
686	            "--por takes a single template path; got '{t}' (drop the `,BOT` half)"
687	        )
688	        .into());
689	    }
690	
691	    if params.config.is_some() && !params.por {
692	        return Err(
693	            "--config is only valid with --por (dual configs are per-side and unconditional)"
694	                .into(),
695	        );
696	    }
697	    if let Some(ConfigKind::Path(p)) = &params.config
698	        && !p.exists()
699	    {
700	        return Err(format!("--config: path does not exist: {}", p.display()).into());
701	    }
702	
703	    let parsed = parse_target(&params.target)?;
704	    debug!("parse_target: {:?} -> {:?}", params.target, parsed);
705	    let plan = match parsed {
706	        Target::Url(url) => plan_from_url(params, scope, url),
707	        Target::OwnerName(o, n) => {
708	            plan_from_url(params, scope, format!("git@github.com:{o}/{n}.git"))
709	        }
710	        Target::Path(p) => plan_from_path(params, scope, p, cfg),
711	        Target::BareName(n) => plan_from_bare_name(params, scope, n, cfg),
712	    }?;
713	    debug!(
714	        "plan_init: project_dir={}, name={}, work_url={}, provisioner={:?}, gh_work_slug={:?}, work_bare_path={:?}, bot_url={:?}",
715	        plan.project_dir.display(),
716	        plan.name,
717	        plan.work_url,
718	        plan.provisioner,
719	        plan.gh_work_slug,
720	        plan.work_bare_path,
721	        plan.bot_url,
722	    );
723	    Ok(plan)
724	}
