726	/// Plan when TARGET is a URL or `owner/name` shorthand.
727	///
728	/// - URL is explicit; config not consulted.
729	/// - `--account` / `--repo` are rejected (would have no effect).
730	/// - `[NAME]` overrides the URL-derived directory name.
731	fn plan_from_url(
732	    params: &InitParams,
733	    scope: Scope,
734	    url: String,
735	) -> Result<InitPlan, Box<dyn std::error::Error>> {
736	    if params.account.is_some() {
737	        return Err(
738	            "--account is meaningless with a URL or owner/name TARGET (config not consulted)"
739	                .into(),
740	        );
741	    }
742	    if params.repo.is_some() {
743	        return Err(
744	            "--repo is meaningless with a URL or owner/name TARGET (config not consulted)".into(),
745	        );
746	    }
747	    let work_url = ensure_git_suffix(&url);
748	    let derived_name = derive_name(&work_url)?;
749	    let name = params.name.clone().unwrap_or(derived_name);
750	    let cwd = std::env::current_dir()?;
751	    let project_dir = cwd.join(&name);
752	
753	    let provisioner = if is_github_url(&work_url) {
754	        Provisioner::GhCreate
755	    } else {
756	        Provisioner::ExternalPreExisting
757	    };
758	    let gh_work_slug = if provisioner == Provisioner::GhCreate {
759	        Some(github_slug_from_url(&work_url)?)
760	    } else {
761	        None
762	    };
763	
764	    build_plan(
765	        scope,
766	        name,
767	        project_dir,
768	        work_url,
769	        provisioner,
770	        gh_work_slug,
771	    )
772	}
