977	/// Resolve a Path target to an absolute `PathBuf`. Handles `~`,
978	/// `~/X`, `$VAR`, `${VAR}` expansion; makes relative paths
979	/// absolute against cwd; lexically normalizes `.` / `..`. The
980	/// resulting path is **not** required to exist (init creates it).
981	fn resolve_path_target(p: &Path) -> Result<PathBuf, Box<dyn std::error::Error>> {
982	    let s = p.to_str().ok_or("path TARGET is not valid UTF-8")?;
983	    let expanded = expand_vars(s)?;
984	    let pb = PathBuf::from(&expanded);
985	    let abs = if pb.is_absolute() {
986	        pb
987	    } else {
988	        std::env::current_dir()?.join(pb)
989	    };
990	    Ok(normalize_path(&abs))
991	}
992	
993	/// Lexically normalize a path: collapse `.` / `..` components
994	/// without touching disk. `std::fs::canonicalize` requires the
995	/// path to exist, but init's destination doesn't yet.
996	fn normalize_path(p: &Path) -> PathBuf {
997	    let mut out: Vec<std::path::Component> = Vec::new();
998	    for comp in p.components() {
999	        match comp {
1000	            std::path::Component::ParentDir => {
1001	                let pop = matches!(
1002	                    out.last(),
1003	                    Some(std::path::Component::Normal(_)) | Some(std::path::Component::CurDir)
1004	                );
1005	                if pop {
1006	                    out.pop();
1007	                } else {
1008	                    out.push(comp);
1009	                }
1010	            }
1011	            std::path::Component::CurDir => {}
1012	            other => out.push(other),
1013	        }
1014	    }
1015	    out.iter().collect()
1016	}
