1018	/// Extract the `owner/name` slug from a GitHub URL (any of the
1019	/// supported forms: SSH scp-like, `ssh://`, `https://`).
1020	fn github_slug_from_url(url: &str) -> Result<String, Box<dyn std::error::Error>> {
1021	    let stem = url.strip_suffix(".git").unwrap_or(url);
1022	    // The slug is the last two path components, `owner/name`.
1023	    if let Some(path) = stem
1024	        .strip_prefix("git@github.com:")
1025	        .or_else(|| stem.strip_prefix("ssh://git@github.com/"))
1026	        .or_else(|| stem.strip_prefix("https://github.com/"))
1027	        .or_else(|| stem.strip_prefix("http://github.com/"))
1028	    {
1029	        let parts: Vec<&str> = path.split('/').collect();
1030	        if parts.len() >= 2 {
1031	            return Ok(format!(
1032	                "{}/{}",
1033	                parts[parts.len() - 2],
1034	                parts[parts.len() - 1]
1035	            ));
1036	        }
1037	    }
1038	    Err(format!("cannot extract owner/name slug from GitHub URL '{url}'").into())
1039	}
