1056	/// Init entry point — runs the dual or POR provisioning flow.
1057	///
1058	/// Takes the shared `Context` (loaded user config) and the flat
1059	/// `InitParams`. CLI builds both at the binary edge in main.rs;
1060	/// tests construct `InitParams` directly.
1061	///
1062	/// `params.create_symlink` controls the `~/.claude/projects/`
1063	/// symlink side effect:
1064	///
1065	/// - `true` — CLI behavior; step 11 creates the symlink for
1066	///   dual-scope runs.
1067	/// - `false` — suppresses that side effect; used by test
1068	///   harnesses (`test_helpers::Fixture`, `test_helpers::FixturePor`)
1069	///   so parallel fixtures don't collide on the user's home dir.
1070	pub fn init(ctx: &Context, params: &InitParams) -> Result<(), Box<dyn std::error::Error>> {
1071	    debug!("init: enter");
1072	
1073	    let create_symlink = params.create_symlink;
1074	    let cfg = &ctx.user_config;
1075	    let plan = plan_init(params, cfg)?;
1076	    let is_dual = plan.scope.is_both();
1077	
1078	    // --- Preflight ---
1079	    info!("Preflight checks...");
1080	
1081	    debug!("verify jj is installed");
1082	    run("jj", &["--version"], Path::new(".")).map_err(|_| "jj is not installed")?;
1083	
1084	    if plan.provisioner == Provisioner::GhCreate {
1085	        debug!("verify gh CLI is installed + authenticated");
1086	        run("gh", &["auth", "status"], Path::new("."))
1087	            .map_err(|_| "gh is not installed or not authenticated (run: gh auth login)")?;
1088	    }
1089	
1090	    if plan.project_dir.exists() {
1091	        return Err(format!("'{}' already exists", plan.project_dir.display()).into());
1092	    }
1093	
1094	    match &plan.provisioner {
1095	        Provisioner::GhCreate => {
1096	            #[allow(clippy::unwrap_used)]
1097	            let work_slug = plan.gh_work_slug.as_ref().unwrap(); // OK: GhCreate path always sets gh_work_slug
1098	            let (work_owner, work_name) = split_slug(work_slug)?;
1099	            if gh_repo_exists(work_owner, work_name)? {
1100	                return Err(format!("GitHub repo '{work_slug}' already exists").into());
1101	            }
1102	            if let Some(bot_slug) = plan.gh_bot_slug.as_ref() {
1103	                let (bot_owner, bot_name) = split_slug(bot_slug)?;
1104	                if gh_repo_exists(bot_owner, bot_name)? {
1105	                    return Err(format!("GitHub repo '{bot_slug}' already exists").into());
1106	                }
1107	            }
1108	        }
1109	        Provisioner::LocalBareInit => {
1110	            #[allow(clippy::unwrap_used)]
1111	            let work_bare = plan.work_bare_path.as_ref().unwrap(); // OK: LocalBareInit path always sets work_bare_path
1112	            if work_bare.exists() {
1113	                return Err(format!(
1114	                    "bare repo '{}' already exists; refusing to clobber",
1115	                    work_bare.display()
1116	                )
1117	                .into());
1118	            }
1119	            if let Some(bot_bare) = plan.bot_bare_path.as_ref()
1120	                && bot_bare.exists()
1121	            {
1122	                return Err(format!(
1123	                    "bare repo '{}' already exists; refusing to clobber",
1124	                    bot_bare.display()
1125	                )
1126	                .into());
1127	            }
1128	        }
1129	        Provisioner::ExternalPreExisting => {
1130	            // For path-shaped URLs: the path must exist (caller
1131	            // pre-created with `git init --bare`). For scheme-URL
1132	            // values we can't preflight cheaply — let git push
1133	            // surface failures.
1134	            if !is_remote_url(&plan.work_url) {
1135	                let p = PathBuf::from(&plan.work_url);
1136	                if !p.exists() {
1137	                    return Err(format!(
1138	                        "--repo-remote: work path '{}' does not exist — \
1139	                         pre-create with `git init --bare`, or use --repo-local for fixture creation",
1140	                        p.display()
1141	                    )
1142	                    .into());
1143	                }
1144	            }
1145	            if let Some(bot_url) = plan.bot_url.as_ref()
1146	                && !is_remote_url(bot_url)
1147	            {
1148	                let p = PathBuf::from(bot_url);
1149	                if !p.exists() {
1150	                    return Err(format!(
1151	                        "--repo-remote: bot path '{}' does not exist — \
1152	                         pre-create with `git init --bare`, or use --repo-local for fixture creation",
1153	                        p.display()
1154	                    )
1155	                    .into());
1156	                }
1157	            }
1158	        }
