1567	        .config_overrides(["init.defaultBranch=main"]);
1568	    gix::ThreadSafeRepository::init_opts(
1569	        path,
1570	        gix::create::Kind::Bare,
1571	        gix::create::Options::default(),
1572	        open_opts,
1573	    )?;
