1	//! The `symlink` subcommand: manage the
2	//! `~/.claude/projects/<encoded-cwd>` symlink that points Claude
3	//! Code's per-project session directory at this workspace's
4	//! `.claude` repo.
5	//!
6	//! Also home to the shared `SymLink` planner (`new` / `with_meta`
7	//! / `create`), `encode_path`, and the `install` helper that
8	//! `vc-x1 init` / `clone` reuse for dual-scope runs.
9	
10	use std::path::{Path, PathBuf};
11	
12	use clap::Args;
13	use log::{debug, info};
14	
15	use crate::context::Context;
16	use crate::subcommand::SubcommandRunner;
17	
18	/// What action the symlink operation needs to take.
19	#[derive(Debug, PartialEq, Eq)]
20	pub enum SymlinkAction {
21	    /// Nothing exists at the symlink path — create it.
22	    Create,
23	    /// An existing symlink points somewhere else — caller must decide whether to replace.
24	    Replace { current_target: PathBuf },
25	    /// The symlink already points to the correct target — nothing to do.
26	    AlreadyCorrect,
27	}
28	
29	/// A planned symlink operation.
30	#[derive(Debug)]
31	pub struct SymLink {
32	    /// Absolute path to the target directory (what the symlink points to).
33	    pub abs_target: PathBuf,
34	    /// Full path of the symlink to create/replace.
35	    pub symlink_path: PathBuf,
36	    /// What action is needed.
37	    pub action: SymlinkAction,
38	}
39	
40	/// Encode a path the way Claude Code does: replace `/` and `.` with `-`.
41	pub fn encode_path(path: &str) -> String {
42	    path.replace(['/', '.'], "-")
43	}
44	
45	/// Read what exists at a path without following symlinks.
46	///
47	/// Returns:
48	/// - `None` — nothing exists
49	/// - `Some(None)` — exists but is not a symlink
50	/// - `Some(Some(target))` — symlink pointing to target
51	fn probe(path: &Path) -> Option<Option<PathBuf>> {
52	    match path.symlink_metadata() {
53	        Err(_) => None,
54	        Ok(meta) => {
55	            if meta.is_symlink() {
56	                Some(Some(std::fs::read_link(path).unwrap_or_default())) // OK: TOCTOU race after symlink_metadata; empty PathBuf forces recreate
57	            } else {
58	                Some(None)
59	            }
60	        }
61	    }
62	}
63	
64	impl SymLink {
65	    /// Plan a symlink operation by probing the filesystem.
66	    ///
67	    /// # Arguments
68	    /// * `cwd` — current working directory (used to derive the symlink name)
69	    /// * `target` — the directory the symlink should point to (resolved to absolute)
70	    /// * `symlink_dir` — parent directory for the symlink (e.g. `~/.claude/projects`)
71	    pub fn new(cwd: &Path, target: &Path, symlink_dir: &Path) -> Result<Self, String> {
72	        let abs_target = if target.is_absolute() {
73	            target.to_path_buf()
74	        } else {
75	            cwd.join(target)
76	        };
77	
78	        let cwd_str = cwd
79	            .to_str()
80	            .ok_or_else(|| "current directory path is not valid UTF-8".to_string())?;
81	        let symlink_name = encode_path(cwd_str);
82	        let symlink_path = symlink_dir.join(symlink_name);
83	
84	        let action = match probe(&symlink_path) {
85	            None => SymlinkAction::Create,
86	            Some(None) => {
87	                return Err(format!(
88	                    "'{}' exists and is not a symlink",
89	                    symlink_path.display()
90	                ));
91	            }
92	            Some(Some(current_target)) => {
93	                if current_target == abs_target {
94	                    SymlinkAction::AlreadyCorrect
95	                } else {
96	                    SymlinkAction::Replace { current_target }
97	                }
98	            }
99	        };
100	
101	        Ok(SymLink {
102	            abs_target,
103	            symlink_path,
104	            action,
105	        })
106	    }
107	
108	    /// Plan a symlink operation from pre-probed metadata (for testing).
109	    #[cfg(test)]
110	    pub fn with_meta(
111	        cwd: &Path,
112	        target: &Path,
113	        symlink_dir: &Path,
114	        symlink_meta: Option<Option<PathBuf>>,
115	    ) -> Result<Self, String> {
116	        let abs_target = if target.is_absolute() {
117	            target.to_path_buf()
118	        } else {
119	            cwd.join(target)
120	        };
121	
122	        let cwd_str = cwd
123	            .to_str()
124	            .ok_or_else(|| "current directory path is not valid UTF-8".to_string())?;
125	        let symlink_name = encode_path(cwd_str);
126	        let symlink_path = symlink_dir.join(symlink_name);
127	
128	        let action = match symlink_meta {
129	            None => SymlinkAction::Create,
130	            Some(None) => {
131	                return Err(format!(
132	                    "'{}' exists and is not a symlink",
133	                    symlink_path.display()
134	                ));
135	            }
136	            Some(Some(current_target)) => {
137	                if current_target == abs_target {
138	                    SymlinkAction::AlreadyCorrect
139	                } else {
140	                    SymlinkAction::Replace { current_target }
141	                }
142	            }
143	        };
144	
145	        Ok(SymLink {
146	            abs_target,
147	            symlink_path,
148	            action,
149	        })
150	    }
151	
152	    /// Execute the symlink operation: create the target dir if needed, create/replace the symlink.
153	    pub fn create(&self, create_target: bool) -> Result<(), String> {
154	        debug!(
155	            "symlink {} -> {}",
156	            self.symlink_path.display(),
157	            self.abs_target.display()
158	        );
159	
160	        if create_target && !self.abs_target.exists() {
161	            std::fs::create_dir_all(&self.abs_target).map_err(|e| {
162	                format!("cannot create target '{}': {e}", self.abs_target.display())
163	            })?;
164	        }
165	
166	        if let Some(parent) = self.symlink_path.parent() {
167	            std::fs::create_dir_all(parent).map_err(|e| {
168	                format!(
169	                    "cannot create symlink directory '{}': {e}",
170	                    parent.display()
171	                )
172	            })?;
173	        }
174	
175	        match &self.action {
176	            SymlinkAction::Create => {}
177	            SymlinkAction::Replace { .. } => {
178	                std::fs::remove_file(&self.symlink_path).map_err(|e| {
179	                    format!(
180	                        "cannot remove existing symlink '{}': {e}",
181	                        self.symlink_path.display()
182	                    )
183	                })?;
184	            }
185	            SymlinkAction::AlreadyCorrect => return Ok(()),
186	        }
187	
188	        #[cfg(unix)]
189	        std::os::unix::fs::symlink(&self.abs_target, &self.symlink_path).map_err(|e| {
190	            format!(
191	                "cannot create symlink '{}' -> '{}': {e}",
192	                self.symlink_path.display(),
193	                self.abs_target.display()
194	            )
195	        })?;
196	
197	        #[cfg(not(unix))]
198	        return Err("symlink creation is only supported on Unix".to_string());
199	
200	        Ok(())
201	    }
202	}
203	
204	/// `~/.claude/projects/` — the standard Claude Code symlink
205	/// directory. Shared default for `install` and the
206	/// `vc-x1 symlink` subcommand.
207	fn default_symlink_dir() -> Result<PathBuf, Box<dyn std::error::Error>> {
208	    let home =
209	        std::env::var("HOME").map_err(|_| "HOME environment variable not set".to_string())?;
210	    Ok(PathBuf::from(home).join(".claude").join("projects"))
211	}
212	
213	/// Install the standard Claude Code workspace symlink for `project_dir`.
214	///
215	/// Links `~/.claude/projects/<encoded>` -> `<project_dir>/.claude`.
216	/// Silent — caller is expected to announce the action (if desired)
217	/// and to include the resulting `SymLink` in any final summary
218	/// output.
219	///
220	/// Shared by `vc-x1 clone --scope=work,bot` and `vc-x1 init
221	/// --scope=work,bot`. The full `vc-x1 symlink` subcommand below
222	/// can't directly call `install` — it has different
223	/// responsibilities (`--target` / `--symlink-dir` overrides,
224	/// replace prompts, `--list`, and `sl.create(true)` vs `false`)
225	/// — but both share `default_symlink_dir` for default-path
226	/// computation.
227	pub fn install(project_dir: &Path) -> Result<SymLink, Box<dyn std::error::Error>> {
228	    let sl = SymLink::new(
229	        project_dir,
230	        &default_bot_target(project_dir),
231	        &default_symlink_dir()?,
232	    )?;
233	    sl.create(false)?;
234	    Ok(sl)
235	}
236	
237	/// Default symlink target: the workspace config's bot dir name —
238	/// honoring a legacy-schema declaration (the clone
239	/// backward-compat path) — falling back to `.claude` when no
240	/// config resolves (e.g. mid-init before both sides exist).
241	fn default_bot_target(project_dir: &Path) -> PathBuf {
242	    crate::common::configured_bot_dir(project_dir)
243	        .ok()
244	        .flatten()
245	        .or_else(|| crate::legacy_vc_config::configured_bot_dir(project_dir))
246	        .and_then(|p| p.file_name().map(PathBuf::from))
247	        .unwrap_or_else(|| PathBuf::from(".claude"))
248	}
249	
250	// -- Subcommand --
251	
252	#[derive(Args, Debug)]
253	pub struct SymlinkArgs {
254	    /// Directory to link to [default: from repos.bot, else .claude]
255	    #[arg(value_name = "TARGET")]
256	    pub target: Option<String>,
257	
258	    /// Directory for symlink [default: ~/.claude/projects]
259	    #[arg(long, value_name = "PATH")]
260	    pub symlink_dir: Option<PathBuf>,
261	
262	    /// List contents of symlinked directory after creation
263	    #[arg(short, long)]
264	    pub list: bool,
265	
266	    /// Replace existing symlink without prompting
267	    #[arg(short, long)]
268	    pub yes: bool,
269	}
270	
271	/// Inputs to the symlink op, flat, owned, clap-free.
272	///
273	/// - `target`: the `TARGET` positional (None ⇒ `.claude`).
274	/// - `symlink_dir`: `--symlink-dir` override (None ⇒
275	///   `~/.claude/projects`).
276	/// - `list`: `-l` / `--list` — list the linked dir's contents
277	///   afterward.
278	/// - `yes`: `-y` / `--yes` — replace an existing symlink without
279	///   prompting.
280	pub struct SymlinkParams {
281	    pub target: Option<String>,
282	    pub symlink_dir: Option<PathBuf>,
283	    pub list: bool,
284	    pub yes: bool,
285	}
286	
287	impl From<&SymlinkArgs> for SymlinkParams {
288	    /// Convert clap-derived `SymlinkArgs` into the flat
289	    /// `SymlinkParams` (total — every field copies straight over).
290	    fn from(a: &SymlinkArgs) -> Self {
291	        Self {
292	            target: a.target.clone(),
293	            symlink_dir: a.symlink_dir.clone(),
294	            list: a.list,
295	            yes: a.yes,
296	        }
297	    }
298	}
299	
300	impl SubcommandRunner for SymlinkArgs {
301	    type Params = SymlinkParams;
302	
303	    /// Delegate to the existing `From<&SymlinkArgs>` impl above
304	    /// (total — never fails).
305	    fn to_params(&self) -> Result<Self::Params, String> {
306	        Ok(SymlinkParams::from(self))
307	    }
308	
309	    /// Run the existing `symlink` op.
310	    fn run(ctx: &mut Context, params: &Self::Params) -> Result<(), Box<dyn std::error::Error>> {
311	        symlink(ctx, params)
312	    }
313	}
314	
315	/// Run the `symlink` subcommand: create — or replace, with a
316	/// prompt unless `--yes` — the `~/.claude/projects/<encoded-cwd>`
317	/// symlink for the current directory.
318	///
319	/// `ctx` is unused today (symlink reads neither user config nor
320	/// the `--log` path); it's present for the uniform subcommand-layer
321	/// signature.
322	pub fn symlink(_ctx: &Context, params: &SymlinkParams) -> Result<(), Box<dyn std::error::Error>> {
323	    debug!("symlink: enter");
324	    let cwd = std::env::current_dir()?;
325	
326	    let target = match &params.target {
327	        Some(t) => PathBuf::from(t),
328	        None => default_bot_target(&cwd),
329	    };
330	
331	    let symlink_dir = match &params.symlink_dir {
332	        Some(d) => d.clone(),
333	        None => default_symlink_dir()?,
334	    };
335	
336	    let sl = SymLink::new(&cwd, &target, &symlink_dir)?;
337	
338	    // Handle interactive prompt for replacement
339	    if let SymlinkAction::Replace { ref current_target } = sl.action {
340	        info!(
341	            "Existing symlink: {} -> {}",
342	            sl.symlink_path.display(),
343	            current_target.display()
344	        );
345	        if !params.yes {
346	            let response = crate::common::prompt("Replace with new target? [y/N] ")?;
347	            if !response.eq_ignore_ascii_case("y") {
348	                return Err("aborted".into());
349	            }
350	        }
351	    }
352	
353	    if sl.action == SymlinkAction::AlreadyCorrect {
354	        info!(
355	            "Already correct: {} -> {}",
356	            sl.symlink_path.display(),
357	            sl.abs_target.display()
358	        );
359	    } else {
360	        sl.create(true)?;
361	        info!(
362	            "Created: {} -> {}",
363	            sl.symlink_path.display(),
364	            sl.abs_target.display()
365	        );
366	    }
367	
368	    if params.list {
369	        let abs_target = if target.is_absolute() {
370	            target
371	        } else {
372	            cwd.join(&target)
373	        };
374	        info!("");
375	        info!("Contents of {}:", abs_target.display());
376	        for entry in std::fs::read_dir(&abs_target)? {
377	            let entry = entry?;
378	            info!("  {}", entry.file_name().to_string_lossy());
379	        }
380	    }
381	
382	    debug!("symlink: exit");
383	    Ok(())
384	}
