1	//! The `validate-bot` subcommand: read-only check that the bot
2	//! repo is in its expected at-rest state.
3	//!
4	//! - `main` must match `main@origin`: the bookmark only moves
5	//!   inside a push / squash-push run, which publishes it in the
6	//!   same invocation, so an at-rest mismatch means an earlier
7	//!   publish was lost (the 0.68.1-diagnosed silent bot-push loss went
8	//!   unnoticed for 8 cycles).
9	//! - Also verifies `main`'s remote refs are tracked.
10	//! - Exits non-zero on any finding and fixes nothing (decided
11	//!   2026-07-15: no automatic fixing) — resolve with
12	//!   `vc-x1 squash-push -R <bot-repo>`.
13	//! - Cheap: two `jj` lookups, no cargo steps — cheap enough for
14	//!   routine use (reacquaint, timers, scripts).
15	
16	use std::path::PathBuf;
17	
18	use clap::Args;
19	use log::{debug, info};
20	
21	use crate::context::Context;
22	use crate::subcommand::SubcommandRunner;
23	
24	/// The bot repo's pinned bookmark — all bot-repo work publishes to
25	/// `main` (mirrors push's `BOT_BOOKMARK`).
26	const BOT_BOOKMARK: &str = "main";
27	
28	/// Check the bot repo's at-rest invariant: `main` published at
29	/// origin (matches `main@origin`) and its remote refs tracked.
30	///
31	/// Read-only; exits non-zero on a mismatch. Fixes nothing — resolve
32	/// with `vc-x1 squash-push -R <bot-repo>`.
33	#[derive(Args, Debug)]
34	pub struct ValidateBotArgs {
35	    /// Path to the bot repo [default: from repos.bot, else .claude]
36	    #[arg(short = 'R', long)]
37	    pub repo: Option<PathBuf>,
38	}
39	
40	/// Per-invocation validate-bot inputs — the clap-free shape the op
41	/// works against.
42	#[derive(Debug)]
43	pub struct ValidateBotParams {
44	    pub repo: PathBuf,
45	}
46	
47	impl TryFrom<&ValidateBotArgs> for ValidateBotParams {
48	    type Error = String;
49	
50	    /// Resolve `-R` (default: the workspace config's bot dir, else
